/* 把「记得的几件事」拼成一行。没有就返回空串。 */
static void facts_build_line(char *buf, size_t cap)
{
    size_t off = 0;

    buf[0] = '\0';
    facts_maybe_reload();

    if (g_fact_count <= 0)
      {
        return;
      }

    facts_append(buf, cap, &off, "你记得关于这个小朋友的这几件事：");

    for (int i = 0; i < g_fact_count; i++)
      {
        if (i > 0)
          {
            facts_append(buf, cap, &off, "；");
          }

        facts_append(buf, cap, &off, g_facts[i]);
      }

    facts_append(buf, cap, &off,
                 "。合适的时候可以自然地提起，但别硬凑、也别一条条念出来。\n");
}

