155	  reg &= ~((0x3u << 7) | 0xfu);             /* clk_src = OSC24M, div_m = 0 */
156	  PWM_REG(LED_PWM_PCCR23) = reg;
157	
158	  /* 打开通道 2 的时钟门控。 */
159	
