        t.eye_open = 140;  t.brow_dy = 12;  t.mouth = FACE_MOUTH_RING;
        t.brow_tilt = -12; t.brow_tilt_r = -12;
        g_prop = PROP_BELL;
      }
    else if (now < g_face_confused_until)
      {
