       ```c
       void led_strip_set_pct(int pct)
       {
         uint32_t active;
         uint32_t reg;

         if (pct < 0) pct = 0;
         else if (pct > 100) pct = 100;

         active = (uint32_t)STRIP_PERIOD_CYCLES * (uint32_t)pct / 100u;

