2240:     * face exists before face_apply() starts reading state into it. */
4306: *   face_apply()       the only thing that runs at runtime:
6165:    face_apply();
===
static bool safety_check(const char *text, const char **hit)
{
    for (int i = 0; g_safety_words[i] != NULL; i++)
