pthread_mutex_unlock(&g_tts_lock);

g_llm_turn = 0;   /* 本地唤醒应答，不是模型轮次 */
busy_mark();

pthread_mutex_lock(&g_msg_lock);
strncpy(g_wake_prompt, text, MSG_BUF_LEN - 1);

