static uint32_t get_pccr_reg_offset(uint32_t channel)
{
    //uint32_t val;

    switch (channel)
    {
        case 0:
        case 1:
            return PWM_PCCR01;
            break;
        case 2:
        case 3:
            return PWM_PCCR23;
            break;
        case 4:
        case 5:
            return PWM_PCCR45;
            break;
        case 6:
        case 7:
            return PWM_PCCR67;
            break;
#ifndef CONFIG_ARCH_SUN20IW2
        case 8:
        case 9:
            return PWM_PCCR8;
            break;
#endif
        default :
            PWM_ERR("channel is error \n");
            return PWM_PCCR01;
    }
}

