90	/*
91	*   pwm_set_clk_src(): pwm clock source selection
92	*
93	*   @channel_in: pwm channel number
94	*       pwm01 pwm23 pwm45 pwm67 pwm89
95	*
96	*   @clk_src: The clock you want to set
97	*       0:OSC24M  1:APB1
98	*/
99	void hal_pwm_clk_src_set(uint32_t channel_in, hal_pwm_clk_src clk_src)
100	{
101	    unsigned long reg_addr = PWM_BASE + PWM_PCCR_BASE;
102	    uint32_t reg_val;
103	
104	    uint32_t channel = channel_in / 2;
105	    reg_addr += 4 * channel;
106	    /*set clock source OSC24M or apb1*/
107	    reg_val = hal_readl(reg_addr);
108	    reg_val = SET_REG_VAL(reg_val, PWM_CLK_SRC_SHIFT, PWM_CLK_SRC_WIDTH, clk_src);
109	    hal_writel(reg_val, reg_addr);
110	}
