static uint32_t count_gpio_bank_mask(void)
{
	uint32_t max_bank = (uint32_t)GPIO_MAX_BANK;
	uint32_t mask = 0;
	do
	{
		mask |= 1 << (max_bank / PINS_PER_BANK);
		max_bank -= PINS_PER_BANK;
		if (max_bank == 0)
		{
			mask |= 1;
		}
	} while (max_bank);
	return mask;
}

