 *
 * v2.89 试过快速扫 2~13 再读回 PIO 的 DAT。结果是 12 档全读到 0，可是
 * 「GPIO 输出拉高读回 1」那个自检也只能证明寄存器能回写——复用成外设
 * 功能以后，这一代的 DAT 未必还反映引脚。所以那条路不能当证据。
 *
 * 现在改成慢的：
 *
 *   1) PG13 当普通输出，拉高 8 秒、拉低 3 秒，再来一次。这 8 秒里量 H4
 *      哪个脚是 3.3V，那根就是 PG13，同时也说明焊盘本身能驱动。
 *   2) 复用值 2~13 每档闪「N 下」（N 就是这个复用号），间隔 1.2 秒。
 *      哪一档闪，哪一档就是 PWM2。数闪几下比对着串口时间戳猜准得多。
 *
 * 探测完恢复成 PWM 和正常亮度。整段约 80 秒，跑在 worker 线程里，不会
 * 拖慢 rcS 和界面启动。 */

static void strip_slow_probe(void)
{
  int mux;
  int n;

  /* PWM 先出 0%，免得和后面的普通输出打架。 */

  PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) = ((STRIP_PERIOD_CYCLES - 1) << 16);

  /* 第 1 段：普通输出，拉高 / 拉低。 */

  hal_gpio_set_pull(STRIP_PIN, GPIO_PULL_DOWN_DISABLED);
  hal_gpio_pinmux_set_function(STRIP_PIN, GPIO_MUXSEL_OUT);

  for (n = 0; n < 2; n++)
    {
      syslog(LOG_INFO, "[led_strip] 慢扫 %d/2：PG13 普通输出拉高 8 秒，"
             "量 H4 哪个脚变 3.3V\n", n + 1);
      hal_gpio_set_data(STRIP_PIN, GPIO_DATA_HIGH);
      usleep(8 * 1000 * 1000);

      syslog(LOG_INFO, "[led_strip] 慢扫 %d/2：拉低 3 秒\n", n + 1);
      hal_gpio_set_data(STRIP_PIN, GPIO_DATA_LOW);
      usleep(3 * 1000 * 1000);
    }

  /* 第 2 段：复用号编成闪灯次数。PWM 给 100% 时闪。 */

  for (mux = 2; mux <= 13; mux++)
    {
      syslog(LOG_INFO, "[led_strip] 慢扫 mux=%d：闪 %d 下\n", mux, mux);

      hal_gpio_pinmux_set_function(STRIP_PIN, (gpio_muxsel_t)mux);

      for (n = 0; n < mux; n++)
        {
          PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) =
              ((STRIP_PERIOD_CYCLES - 1) << 16) | STRIP_PERIOD_CYCLES;
          usleep(250 * 1000);

          PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) =
              ((STRIP_PERIOD_CYCLES - 1) << 16);
          usleep(250 * 1000);
        }

      usleep(1200 * 1000);
    }

  syslog(LOG_INFO, "[led_strip] 慢扫结束，回到 mux=%d\n", g_strip_pwm_mux);

  hal_gpio_pinmux_set_function(STRIP_PIN, (gpio_muxsel_t)g_strip_pwm_mux);
  hal_gpio_set_pull(STRIP_PIN, GPIO_PULL_DOWN);
}

