/* 自动探测 PG13 到底复用成哪一档才是 PWM2。
 *
 * 原理图里 PG13 的功能表是
 *   I2S1_BCLK / TWI0_SDA / RGMII_CLKIN / RMII_RXER / PWM2 / LEDC_DO / UART1_RX
 * 按「第一个复用 = 2」数下来 PWM2 是 6。真机上 mux=6 时通道寄存器全对、
 * 计数器也在跑，脚上却没有电平。与其继续照着文档猜，不如直接问硬件：
 * 2~13 每档都试一遍，PWM 通道 2 分别给 100% 和 0%，再读回引脚电平——
 * 哪个档位跟着变，哪个就是 PWM2。
 *
 * 读的是 PIO 的 DAT 寄存器，反映引脚电平，不是最后写进去的值。先用普通
 * 输出模式验一次这个读法本身有没有用：万一这一代在复用模式下读不到引脚，
 * 日志里能直接看出来，那就只能拿万用表量。
 *
 * 返回找到的复用号；没找到返回 -1，调用方保持默认值。 */

static int strip_probe_mux(void)
{
  gpio_data_t hi;
  gpio_data_t lo;
  int         mux;
  int         found = -1;

  hal_gpio_pinmux_set_function(STRIP_PIN, GPIO_MUXSEL_OUT);

  hal_gpio_set_data(STRIP_PIN, GPIO_DATA_HIGH);
  usleep(2 * 1000);
  (void)hal_gpio_get_data(STRIP_PIN, &hi);

  hal_gpio_set_data(STRIP_PIN, GPIO_DATA_LOW);
  usleep(2 * 1000);
  (void)hal_gpio_get_data(STRIP_PIN, &lo);

  syslog(LOG_INFO, "[led_strip] probe gpio-out: 高=%d 低=%d（读回%s）\n",
         (int)hi, (int)lo,
         (hi == GPIO_DATA_HIGH && lo == GPIO_DATA_LOW) ? "可用" : "不可用");

  for (mux = 2; mux <= 13; mux++)
    {
      hal_gpio_pinmux_set_function(STRIP_PIN, (gpio_muxsel_t)mux);

      PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) =
          ((STRIP_PERIOD_CYCLES - 1) << 16) | STRIP_PERIOD_CYCLES;
      usleep(2 * 1000);
      (void)hal_gpio_get_data(STRIP_PIN, &hi);

      PWM_REG(LED_PWM_PPR(STRIP_PWM_CH)) =
          ((STRIP_PERIOD_CYCLES - 1) << 16);
      usleep(2 * 1000);
      (void)hal_gpio_get_data(STRIP_PIN, &lo);

      syslog(LOG_INFO, "[led_strip] probe mux=%d: 100%%=%d 0%%=%d\n",
             mux, (int)hi, (int)lo);

      if (hi == GPIO_DATA_HIGH && lo == GPIO_DATA_LOW)
        {
          found = mux;
          break;
        }
    }

  return found;
}

