void cmd_set_mqtt(int argc, char** argv)
{
    if (argc < 2) {
        printf("Usage: set_mqtt <host:port> [client_id [topic_in topic_out "
               "[username password]]]\n"
               "  e.g. set_mqtt bemfa.com:9501 kid-buddy kb/in kb/out appid secret\n"
               "       set_mqtt 192.168.1.100:1883\n");
        return;
    }

    claw_config_set(AGENT_CFG_KEY_MQTT_BROKER, argv[1]);
    if (argc >= 3) {
        claw_config_set(AGENT_CFG_KEY_MQTT_CLIENT_ID, argv[2]);
    }
    if (argc >= 5) {
        claw_config_set(AGENT_CFG_KEY_MQTT_TOPIC_IN, argv[3]);
        claw_config_set(AGENT_CFG_KEY_MQTT_TOPIC_OUT, argv[4]);
    }
    if (argc >= 7) {
        claw_config_set(AGENT_CFG_KEY_MQTT_USERNAME, argv[5]);
        claw_config_set(AGENT_CFG_KEY_MQTT_PASSWORD, argv[6]);
    }

    /* Re-init and start immediately so no restart is needed */
    mqtt_channel_stop();
    mqtt_channel_init();
    mqtt_channel_start();
    printf("MQTT broker set to %s and started.\n", argv[1]);
    if (argc >= 5) {
        printf("  topics: %s <- / -> %s\n", argv[3], argv[4]);
    }
    if (argc >= 7) {
        printf("  auth: user=%s pass=%s\n", argv[5], "***");
    }
}

