            cJSON *to_j   = cJSON_GetObjectItem(root, "to");
            cJSON *cid    = cJSON_GetObjectItem(root, "chat_id");
            const char *cid_s = (cJSON_IsString(cid) && cid->valuestring[0])
                                ? cid->valuestring : "mqtt_default";
