```c
#define MQTT_ACK_QUEUE 4
static pthread_mutex_t s_ack_lock = PTHREAD_MUTEX_INITIALIZER;
static char s_ack_to[MQTT_ACK_QUEUE][64];
static char s_ack_text[MQTT_ACK_QUEUE][192];
static int s_ack_head, s_ack_tail;

static void mqtt_ack_defer(const char *to, const char *text)
{
    if (!to || !text) return;
    pthread_mutex_lock(&s_ack_lock);
    int next = (s_ack_head + 1) % MQTT_ACK_QUEUE;
    if (next != s_ack_tail) {
        strncpy(s_ack_to[s_ack_head], to, 63); ...
        strncpy(s_ack_text[s_ack_head], text, 191); ...
        s_ack_head = next;
    } else {
        syslog(LOG_WARNING, "[%s] ack queue full, drop: %s\n", TAG, text);
    }
    pthread_mutex_unlock(&s_ack_lock);
}

static void mqtt_ack_pump(void)
{
    char to[64], text[192];
    while (1) {
        pthread_mutex_lock(&s_ack_lock);
        if (s_ack_tail == s_ack_head) { pthread_mutex_unlock(&s_ack_lock); return; }
        strcpy(to, s_ack_to[s_ack_tail]); strcpy(text, s_ack_text[s_ack_tail]);
        s_ack_tail = (s_ack_tail + 1) % MQTT_ACK_QUEUE;
        pthread_mutex_unlock(&s_ack_lock);
        mqtt_channel_send(to, text);
    }
}
