function escHtml(s){
  return String(s).replace(/[&<>"]/g, function(c){
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

/* 一次冒险 = 一组时间挨得近的往来。板子不告诉我们会话边界，
 * 按间隔 30 分钟切分 —— 孩子中间跑去吃饭再回来，算新的一段。
 * 卡片列表和故事书共用这一份，免得两边走偏。 */
function groupAdventures(rows){
  rows.sort(function(a, b){ return (a.ts || 0) - (b.ts || 0); });

  var groups = [], cur = null;
  rows.forEach(function(r){
    if (!cur || ((r.ts || 0) - cur.end) > 1800) {
      cur = { start: r.ts || 0, end: r.ts || 0, items: [] };
      groups.push(cur);
    }
    cur.items.push(r);
    if ((r.ts || 0) > cur.end) cur.end = r.ts || 0;
  });

  return groups;
}

/* ── 故事书 ──────────────────────────────────────────────────
 *
 * 把冒险记录排成一本能读的书，用浏览器自带的「打印 → 存为 PDF」导出。
 * 这么做而不是自己生成 PDF/图片，是因为**零依赖**：不用引任何库，
 * 手机上也能直接导。
 *
 * 版面上刻意做了区分：故事正文用宋体、字大行疏，孩子的每一句另外标出来
 * （换无衬线字体 + 左侧竖线 + 蓝色）—— 家长翻这本的时候，
 * 想看的其实是**孩子说了什么**，而不是故事本身。 */

var CHAPTER_NAMES = ['第一章','第二章','第三章','第四章','第五章',
                     '第六章','第七章','第八章','第九章','第十章',
                     '第十一章','第十二章','第十三章','第十四章','第十五章'];

function openBook(){
  dbOpen(function(d){
    if (!d) return;
    var rows = [];
    var tx = d.transaction(STORY_STORE, 'readonly');
    tx.objectStore(STORY_STORE).openCursor().onsuccess = function(e){
      var c = e.target.result;
      if (!c) { drawBook(rows); return; }
      rows.push(c.value);
      c.continue();
    };
  });
}

function drawBook(rows){
  var el = $('bookBody');

  if (!rows.length) {
    el.innerHTML = '<div class="book-cover"><div class="book-kicker">kid_buddy</div>' +
                   '<h1>还没有故事</h1>' +
                   '<p class="book-meta">孩子在板子上玩过冒险之后，回来点「同步」就有了。</p></div>';
    $('book').classList.add('show');
    return;
  }

  var groups = groupAdventures(rows);
  var first = groups[0].start;
  var last  = groups[groups.length - 1].end;

  var html = '<div class="book-cover">' +
             '<div class="book-kicker">kid_buddy</div>' +
             '<h1>孩子的冒险故事</h1>' +
             '<div class="book-meta">' + fmtDay(first) + ' — ' + fmtDay(last) +
             '　·　一共 ' + groups.length + ' 段冒险</div></div>';

  groups.forEach(function(g, i) {
    html += '<section class="book-chapter">';
    html += '<h2>' + (CHAPTER_NAMES[i] || ('第 ' + (i + 1) + ' 章')) +
            '　·　' + fmtDay(g.start) + '</h2>';
    g.items.forEach(function(r) {
      if (r.role === 'user') {
        html += '<p class="book-kid">' + escHtml(r.content) + '</p>';
      } else {
        html += '<p class="book-say">' + escHtml(r.content) + '</p>';
      }
    });
    html += '</section>';
  });

  el.innerHTML = html;
  $('book').classList.add('show');
  $('book').scrollTop = 0;
}

function closeBook(){
  $('book').classList.remove('show');
}

function printBook(){
  window.print();
